class Solution:
    def countAnagrams(self, s: str) -> int:
        MOD = 10**9 + 7
        n = max(len(w) for w in s.split(' '))
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i-1] * i % MOD
        ans = 1
        for w in s.split(' '):
            ans = ans * fact[len(w)] % MOD
            cnt = Counter(w)
            for c in cnt.values():
                ans = ans * pow(fact[c], MOD - 2, MOD) % MOD
        return ans

