class Solution {
public:
    static constexpr long long MOD = 1e9 + 7;
    long long pw(long long b, long long e) {
        long long r = 1; b %= MOD;
        while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
        return r;
    }
    int countAnagrams(string s) {
        int mx = 0;
        for (char c : s) if (c != ' ') mx++;
        vector<long long> fact(mx + 1, 1);
        for (int i = 1; i <= mx; i++) fact[i] = fact[i-1] * i % MOD;
        long long ans = 1;
        int cnt[26];
        stringstream ss(s); string w;
        while (ss >> w) {
            memset(cnt, 0, sizeof(cnt));
            for (char c : w) cnt[c - 'a']++;
            ans = ans * fact[w.size()] % MOD;
            for (int k = 0; k < 26; k++)
                if (cnt[k] > 1) ans = ans * pw(fact[cnt[k]], MOD - 2) % MOD;
        }
        return (int)ans;
    }
};

