class Solution {
    private static final long MOD = 1_000_000_007L;
    private long pw(long b, long e) {
        long r = 1; b %= MOD;
        while (e > 0) { if ((e & 1) == 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
        return r;
    }
    public int countAnagrams(String s) {
        String[] words = s.split(" ");
        int mx = 0;
        for (String w : words) mx = Math.max(mx, w.length());
        long[] fact = new long[mx + 1];
        fact[0] = 1;
        for (int i = 1; i <= mx; i++) fact[i] = fact[i-1] * i % MOD;
        long ans = 1;
        for (String w : words) {
            int[] cnt = new int[26];
            for (char c : w.toCharArray()) cnt[c - 'a']++;
            ans = ans * fact[w.length()] % MOD;
            for (int k = 0; k < 26; k++)
                if (cnt[k] > 1) ans = ans * pw(fact[cnt[k]], MOD - 2) % MOD;
        }
        return (int) ans;
    }
}

