var countAnagrams = function(s) {
    const MOD = 1000000007n;
    const words = s.split(' ');
    const mx = Math.max(...words.map(w => w.length));
    const fact = new Array(mx + 1).fill(1n);
    for (let i = 1; i <= mx; i++) fact[i] = fact[i-1] * BigInt(i) % MOD;
    const pw = (b, e) => {
        let r = 1n; b %= MOD;
        while (e > 0n) { if (e & 1n) r = r * b % MOD; b = b * b % MOD; e >>= 1n; }
        return r;
    };
    let ans = 1n;
    for (const w of words) {
        const cnt = new Array(26).fill(0);
        for (const c of w) cnt[c.charCodeAt(0) - 97]++;
        ans = ans * fact[w.length] % MOD;
        for (const c of cnt)
            if (c > 1) ans = ans * pw(fact[c], MOD - 2n) % MOD;
    }
    return Number(ans);
};
